draw:
var g = 9.8, v0 = p.v0;
var tf = 2 * v0 / g;
var tp = v0 / g;
var hmax = v0 * v0 / (2 * g);
var pad = 34;
var colW = (W - pad * 2 - 24) / 3;
var gh = H - pad - 26;
var top = pad;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

function axes(x0, title) {
  ctx.strokeStyle = C.rule;
  ctx.beginPath();
  ctx.moveTo(x0, top);
  ctx.lineTo(x0, top + gh);
  ctx.lineTo(x0 + colW, top + gh);
  ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText(title, x0, top - 10);
  ctx.fillStyle = C.faint;
  ctx.fillText("t", x0 + colW - 6, top + gh + 15);
}

/* panel 1: height against time */
var x1 = pad;
axes(x1, "y (m)");
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var s = tf * i / 120;
  var y = v0 * s - 0.5 * g * s * s;
  var px = x1 + colW * s / tf;
  var py = top + gh - (gh - 10) * y / hmax;
  i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
}
ctx.stroke();
ctx.setLineDash([3, 4]); ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x1, top + 10); ctx.lineTo(x1 + colW / 2, top + 10); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x1 + colW / 2, top + 10); ctx.lineTo(x1 + colW / 2, top + gh); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText(hmax.toFixed(1), x1 - 30, top + 14);
ctx.fillText(tp.toFixed(2) + " s", x1 + colW / 2 - 12, top + gh + 15);

/* panel 2: velocity against time */
var x2 = pad + colW + 12;
axes(x2, "v (m/s)");
var mid = top + gh / 2;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x2, mid); ctx.lineTo(x2 + colW, mid); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x2, mid - (gh / 2 - 8));
ctx.lineTo(x2 + colW, mid + (gh / 2 - 8));
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("+" + v0.toFixed(0), x2 - 26, mid - gh / 2 + 12);
ctx.fillText("-" + v0.toFixed(0), x2 - 26, mid + gh / 2 - 2);
ctx.fillText("slope = -g", x2 + 6, mid - 8);

/* panel 3: acceleration against time */
var x3 = pad + 2 * colW + 24;
axes(x3, "a (m/s^2)");
var mid3 = top + gh / 2;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x3, mid3); ctx.lineTo(x3 + colW, mid3); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(x3, mid3 + gh * 0.22);
ctx.lineTo(x3 + colW, mid3 + gh * 0.22);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("-9.8, flat", x3 + 6, mid3 + gh * 0.22 - 7);

/* moving cursor tying the three panels together */
var now = t % tf;
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.setLineDash([2, 3]);
var cols = [x1, x2, x3];
for (var k = 0; k < 3; k++) {
  var cxk = cols[k] + colW * now / tf;
  ctx.beginPath(); ctx.moveTo(cxk, top); ctx.lineTo(cxk, top + gh); ctx.stroke();
}
ctx.setLineDash([]);

var yc = v0 * now - 0.5 * g * now * now;
var vc = v0 - g * now;
out.note = "t = " + now.toFixed(2) + " s: y = " + yc.toFixed(1) + " m, v = " + vc.toFixed(1) +
  " m/s, a = -9.80 m/s^2 the whole way";
